import React, { useEffect, useState } from 'react';
import {
  ResponsiveContainer,
  PieChart, Pie, Cell,
  BarChart, Bar, XAxis, YAxis, Tooltip
} from 'recharts';
import { loadDashboardData } from '../api/dashboard';

const RISK_COLORS = { safe: '#60a5fa', warning: '#facc15', danger: '#ef4444' };
const VULN_COLORS = { low: '#10b981', medium: '#f59e0b', high: '#ef4444' };

export default function DashboardPage() {
  const [data, setData]     = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const d = await loadDashboardData();
        setData(d);
      } catch (e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  if (loading) return <p className="text-center py-8">불러오는 중…</p>;
  if (error)   return <p className="text-red-500 text-center py-8">{error}</p>;

  const { summary, riskCounts, vulnCounts } = data;

  // 차트용 데이터 포맷
  const riskPieData = Object.entries(riskCounts)
    .map(([k,v]) => ({ name:k, value:v }))
    .filter(x=>x.value>0);

  const vulnPieData = Object.entries(vulnCounts)
    .map(([k,v]) => ({ name:k, value:v }))
    .filter(x=>x.value>0);

  return (
    <main className="max-w-5xl mx-auto p-6 font-sans space-y-8">
      <h1 className="text-3xl font-bold">포트스캐너 대시보드</h1>

      {/* 요약 카드 */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white shadow rounded p-4">
          <p className="text-sm text-gray-500">전체 자산 수</p>
          <p className="text-3xl font-semibold">{summary.total_assets}</p>
        </div>
        <div className="bg-white shadow rounded p-4">
          <p className="text-sm text-gray-500">위험 자산 수</p>
          <p className="text-3xl font-semibold">{summary.risky_assets}</p>
        </div>
        <div className="bg-white shadow rounded p-4">
          <p className="text-sm text-gray-500">Critical CVE 건수</p>
          <p className="text-3xl font-semibold">{summary.critical_cves}</p>
        </div>
      </div>

      {/* 차트 그리드 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-white shadow rounded p-4">
          <h3 className="text-lg mb-2">위험도 분포</h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={riskPieData}
                dataKey="value"
                nameKey="name"
                outerRadius={80}
                label
              >
                {riskPieData.map((e,i)=>(
                  <Cell key={i} fill={RISK_COLORS[e.name]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white shadow rounded p-4">
          <h3 className="text-lg mb-2">취약점 심각도 분포</h3>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={vulnPieData}
                dataKey="value"
                nameKey="name"
                outerRadius={80}
                label
              >
                {vulnPieData.map((e,i)=>(
                  <Cell key={i} fill={VULN_COLORS[e.name]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white shadow rounded p-4">
        <h3 className="text-lg mb-2">자산별 열린 포트 수</h3>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart
            data={summary.assets.map(a=>({ name:a.name, openPorts:a.ports_count }))}
          >
            <XAxis dataKey="name" />
            <YAxis allowDecimals={false} />
            <Tooltip />
            <Bar dataKey="openPorts" fill="#3b82f6" />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </main>
  );
}
